def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n.

    Raises ValueError if n is negative or is not a perfect square.
    """
    if n < 0:
        raise ValueError("negative input")
    if not isinstance(n, int):
        raise ValueError("integer input required")

    # Newton's method with integer arithmetic: exact for every size, no
    # floating-point round-off.
    if n < 2:
        return n
    x = 1 << ((n.bit_length() + 1) // 2)  # x > sqrt(n)
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    if x * x != n:
        raise ValueError("%d is not a perfect square" % n)
    return x
